void g_Tiles_DrawBlock(u8 x, u8 y, u16 base, u8 w, u8 h)
{
	VDP_WriteLayout_GM2(g_Tiles_Blocks + base, x, y, w, h);
}

extern const u8 g_CoinAnim_Patterns[];
extern const u8 g_CoinAnim_Durations[];

static const u8* const g_Tiles_AnimDurations[G_TILES_ANIMS] = { g_CoinAnim_Durations };
static const u8 g_Tiles_AnimLength[G_TILES_ANIMS] = { 4 };
// 0 loop, 1 ping-pong, 2 once (holds the last pose).
static const u8 g_Tiles_AnimLoop[G_TILES_ANIMS] = { 0 };
static u8 g_Tiles_AnimFrame[G_TILES_ANIMS];
static u8 g_Tiles_AnimTick[G_TILES_ANIMS];
// Bit 0: playing. Bit 1: running backwards (ping-pong).
static u8 g_Tiles_AnimState[G_TILES_ANIMS];

static void g_Tiles_AnimShow(u8 anim, u8 frame)
{
	switch(anim)
	{
	case 0: // g_CoinAnim → tile 6, every bank
		VDP_LoadPattern_GM2(g_CoinAnim_Patterns + (u16)frame * 8, 1, 6);
		break;
	}
}

void g_Tiles_AnimRestart(u8 anim)
{
	if(anim >= G_TILES_ANIMS) return;
	g_Tiles_AnimFrame[anim] = 0;
	g_Tiles_AnimTick[anim] = 0;
	g_Tiles_AnimState[anim] = 1;
	g_Tiles_AnimShow(anim, 0);
}

void g_Tiles_AnimReset(void)
{
	for(u8 i = 0; i < G_TILES_ANIMS; ++i) g_Tiles_AnimRestart(i);
}

void g_Tiles_Animate(void)
{
	for(u8 i = 0; i < G_TILES_ANIMS; ++i)
	{
		u8 state = g_Tiles_AnimState[i];
		if(!(state & 1)) continue;
		const u8 last = g_Tiles_AnimLength[i] - 1;
		u8 f = g_Tiles_AnimFrame[i];
		// Clamped: a frame index past the end means _AnimReset() never ran.
		if(f > last) f = 0;
		if(++g_Tiles_AnimTick[i] < g_Tiles_AnimDurations[i][f]) continue;
		g_Tiles_AnimTick[i] = 0;
		if(g_Tiles_AnimLoop[i] == 1)
		{
			if(state & 2) { if(f == 0) { state &= ~2; if(last) f = 1; } else --f; }
			else { if(f >= last) { state |= 2; if(last) f = last - 1; } else ++f; }
		}
		else if(f < last) ++f;
		else if(g_Tiles_AnimLoop[i] == 2) { g_Tiles_AnimState[i] = state & ~1; continue; }
		else f = 0;
		g_Tiles_AnimState[i] = state;
		g_Tiles_AnimFrame[i] = f;
		g_Tiles_AnimShow(i, f);
	}
}

void g_Tiles_AnimSetActive(u8 anim, bool on)
{
	if(anim >= G_TILES_ANIMS) return;
	if(on) g_Tiles_AnimState[anim] |= 1;
	else g_Tiles_AnimState[anim] &= ~1;
}

u8 g_Tiles_AnimGetFrame(u8 anim)
{
	if(anim >= G_TILES_ANIMS) return 0;
	const u8 f = g_Tiles_AnimFrame[anim];
	// The same clamp _Animate() applies, so the two never disagree.
	return f < g_Tiles_AnimLength[anim] ? f : 0;
}
